// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetAdminLog The admin log
	// (GET /admin/log)
	GetAdminLog(w http.ResponseWriter, r *http.Request, params GetAdminLogParams)
	// GetAdminUsers Search the accounts
	// (GET /admin/users)
	GetAdminUsers(w http.ResponseWriter, r *http.Request, params GetAdminUsersParams)
	// UnbanUser Lift a player's ban
	// (DELETE /admin/users/{userId}/ban)
	UnbanUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// BanUser Ban a player
	// (POST /admin/users/{userId}/ban)
	BanUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// UnmuteUser Lift a player's mute
	// (DELETE /admin/users/{userId}/mute)
	UnmuteUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// MuteUser Mute a player in the lobby chat
	// (POST /admin/users/{userId}/mute)
	MuteUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// SetUserPassword Give a player a new password
	// (PUT /admin/users/{userId}/password)
	SetUserPassword(w http.ResponseWriter, r *http.Request, userId UserId)
	// SetUserRole Make a player an admin, or an admin a player
	// (PUT /admin/users/{userId}/role)
	SetUserRole(w http.ResponseWriter, r *http.Request, userId UserId)
	// LogIn Log in
	// (POST /auth/login)
	LogIn(w http.ResponseWriter, r *http.Request)
	// LogOut Log out
	// (POST /auth/logout)
	LogOut(w http.ResponseWriter, r *http.Request)
	// GetCurrentAccount The account that is logged in
	// (GET /auth/me)
	GetCurrentAccount(w http.ResponseWriter, r *http.Request)
	// ChangePassword Change the password
	// (POST /auth/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// SignUp Create an account and log it in
	// (POST /auth/signup)
	SignUp(w http.ResponseWriter, r *http.Request)
	// SearchCards Search the card catalogue
	// (GET /cards)
	SearchCards(w http.ResponseWriter, r *http.Request, params SearchCardsParams)
	// GetCardFilters The values the card search can filter by
	// (GET /cards/filters)
	GetCardFilters(w http.ResponseWriter, r *http.Request)
	// GetCardImage A card's picture
	// (GET /cards/images/{key})
	GetCardImage(w http.ResponseWriter, r *http.Request, key string)
	// GetCardSetIcon A set's icon
	// (GET /cards/sets/{setCode}/icon)
	GetCardSetIcon(w http.ResponseWriter, r *http.Request, setCode string)
	// GetCard One card, with every printing
	// (GET /cards/{cardId})
	GetCard(w http.ResponseWriter, r *http.Request, cardId string)
	// GetChat The latest lobby chat messages, oldest first
	// (GET /chat)
	GetChat(w http.ResponseWriter, r *http.Request)
	// PostChatMessage Post to the lobby chat
	// (POST /chat)
	PostChatMessage(w http.ResponseWriter, r *http.Request)
	// ListDecks The player's decks, the most recently changed first
	// (GET /decks)
	ListDecks(w http.ResponseWriter, r *http.Request)
	// CreateDeck Create a deck
	// (POST /decks)
	CreateDeck(w http.ResponseWriter, r *http.Request)
	// ReadDeckList Read a deck list written as text
	// (POST /decks/text)
	ReadDeckList(w http.ResponseWriter, r *http.Request)
	// DeleteDeck Delete a deck
	// (DELETE /decks/{deckId})
	DeleteDeck(w http.ResponseWriter, r *http.Request, deckId string)
	// GetDeck One of the player's decks, with its cards and legality
	// (GET /decks/{deckId})
	GetDeck(w http.ResponseWriter, r *http.Request, deckId string)
	// UpdateDeck Replace a deck
	// (PUT /decks/{deckId})
	UpdateDeck(w http.ResponseWriter, r *http.Request, deckId string)
	// GetDeckText A deck written as text
	// (GET /decks/{deckId}/text)
	GetDeckText(w http.ResponseWriter, r *http.Request, deckId string)
	// ListFormats Every format, in the order admins set
	// (GET /formats)
	ListFormats(w http.ResponseWriter, r *http.Request)
	// GetLiveGame A running game, for its players and its spectators
	// (GET /games/{gameId})
	GetLiveGame(w http.ResponseWriter, r *http.Request, gameId string)
	// OpenGameSocket Play or watch a game
	// (GET /games/{gameId}/socket)
	OpenGameSocket(w http.ResponseWriter, r *http.Request, gameId string)
	// GetHealth Check that the server and its database are working
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// GetLobby The lobby as players see it
	// (GET /lobby)
	GetLobby(w http.ResponseWriter, r *http.Request)
	// OpenGame Open a game for an opponent to join
	// (POST /lobby/games)
	OpenGame(w http.ResponseWriter, r *http.Request)
	// CancelOpenGame Cancel an open game; only its host may
	// (DELETE /lobby/games/{openGameId})
	CancelOpenGame(w http.ResponseWriter, r *http.Request, openGameId string)
	// GetOpenGame An open game, listed or not, as its invite link shows it
	// (GET /lobby/games/{openGameId})
	GetOpenGame(w http.ResponseWriter, r *http.Request, openGameId string)
	// JoinOpenGame Join an open game, which starts it
	// (POST /lobby/games/{openGameId}/join)
	JoinOpenGame(w http.ResponseWriter, r *http.Request, openGameId string)
	// GetMatch A finished game
	// (GET /matches/{gameId})
	GetMatch(w http.ResponseWriter, r *http.Request, gameId string)
	// GetPlayer A player's profile
	// (GET /players/{username})
	GetPlayer(w http.ResponseWriter, r *http.Request, username string)
	// GetPlayerMatches A player's match history
	// (GET /players/{username}/matches)
	GetPlayerMatches(w http.ResponseWriter, r *http.Request, username string, params GetPlayerMatchesParams)
	// LeaveQuickMatch Stop waiting for a quick match
	// (DELETE /quick-match)
	LeaveQuickMatch(w http.ResponseWriter, r *http.Request)
	// GetQuickMatch Quick match as the player sees it
	// (GET /quick-match)
	GetQuickMatch(w http.ResponseWriter, r *http.Request)
	// EnterQuickMatch Wait for a quick match
	// (POST /quick-match)
	EnterQuickMatch(w http.ResponseWriter, r *http.Request)
	// GetRankings The rankings
	// (GET /rankings)
	GetRankings(w http.ResponseWriter, r *http.Request, params GetRankingsParams)
	// OpenRealtime Open the live connection
	// (GET /realtime)
	OpenRealtime(w http.ResponseWriter, r *http.Request)
	// DeclineRematch Decline the rematch, or leave it for the lobby
	// (DELETE /rematches/{gameId})
	DeclineRematch(w http.ResponseWriter, r *http.Request, gameId string)
	// GetRematch The rematch of a game that just ended, for its players
	// (GET /rematches/{gameId})
	GetRematch(w http.ResponseWriter, r *http.Request, gameId string)
	// ChooseRematchDeck Switch to another deck for the rematch
	// (PUT /rematches/{gameId}/deck)
	ChooseRematchDeck(w http.ResponseWriter, r *http.Request, gameId string)
	// AgreeToRematch Offer the rematch, or accept the other player's
	// (POST /rematches/{gameId}/ready)
	AgreeToRematch(w http.ResponseWriter, r *http.Request, gameId string)
	// GetSiteStats How many players are online and games running
	// (GET /stats)
	GetSiteStats(w http.ResponseWriter, r *http.Request)
}

