// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetAdminLog The admin log
	// (GET /admin/log)
	GetAdminLog(ctx context.Context, request GetAdminLogRequestObject) (GetAdminLogResponseObject, error)
	// GetAdminUsers Search the accounts
	// (GET /admin/users)
	GetAdminUsers(ctx context.Context, request GetAdminUsersRequestObject) (GetAdminUsersResponseObject, error)
	// UnbanUser Lift a player's ban
	// (DELETE /admin/users/{userId}/ban)
	UnbanUser(ctx context.Context, request UnbanUserRequestObject) (UnbanUserResponseObject, error)
	// BanUser Ban a player
	// (POST /admin/users/{userId}/ban)
	BanUser(ctx context.Context, request BanUserRequestObject) (BanUserResponseObject, error)
	// UnmuteUser Lift a player's mute
	// (DELETE /admin/users/{userId}/mute)
	UnmuteUser(ctx context.Context, request UnmuteUserRequestObject) (UnmuteUserResponseObject, error)
	// MuteUser Mute a player in the lobby chat
	// (POST /admin/users/{userId}/mute)
	MuteUser(ctx context.Context, request MuteUserRequestObject) (MuteUserResponseObject, error)
	// SetUserPassword Give a player a new password
	// (PUT /admin/users/{userId}/password)
	SetUserPassword(ctx context.Context, request SetUserPasswordRequestObject) (SetUserPasswordResponseObject, error)
	// SetUserRole Make a player an admin, or an admin a player
	// (PUT /admin/users/{userId}/role)
	SetUserRole(ctx context.Context, request SetUserRoleRequestObject) (SetUserRoleResponseObject, error)
	// LogIn Log in
	// (POST /auth/login)
	LogIn(ctx context.Context, request LogInRequestObject) (LogInResponseObject, error)
	// LogOut Log out
	// (POST /auth/logout)
	LogOut(ctx context.Context, request LogOutRequestObject) (LogOutResponseObject, error)
	// GetCurrentAccount The account that is logged in
	// (GET /auth/me)
	GetCurrentAccount(ctx context.Context, request GetCurrentAccountRequestObject) (GetCurrentAccountResponseObject, error)
	// ChangePassword Change the password
	// (POST /auth/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// SignUp Create an account and log it in
	// (POST /auth/signup)
	SignUp(ctx context.Context, request SignUpRequestObject) (SignUpResponseObject, error)
	// SearchCards Search the card catalogue
	// (GET /cards)
	SearchCards(ctx context.Context, request SearchCardsRequestObject) (SearchCardsResponseObject, error)
	// GetCardFilters The values the card search can filter by
	// (GET /cards/filters)
	GetCardFilters(ctx context.Context, request GetCardFiltersRequestObject) (GetCardFiltersResponseObject, error)
	// GetCardImage A card's picture
	// (GET /cards/images/{key})
	GetCardImage(ctx context.Context, request GetCardImageRequestObject) (GetCardImageResponseObject, error)
	// GetCardSetIcon A set's icon
	// (GET /cards/sets/{setCode}/icon)
	GetCardSetIcon(ctx context.Context, request GetCardSetIconRequestObject) (GetCardSetIconResponseObject, error)
	// GetCard One card, with every printing
	// (GET /cards/{cardId})
	GetCard(ctx context.Context, request GetCardRequestObject) (GetCardResponseObject, error)
	// GetChat The latest lobby chat messages, oldest first
	// (GET /chat)
	GetChat(ctx context.Context, request GetChatRequestObject) (GetChatResponseObject, error)
	// PostChatMessage Post to the lobby chat
	// (POST /chat)
	PostChatMessage(ctx context.Context, request PostChatMessageRequestObject) (PostChatMessageResponseObject, error)
	// ListDecks The player's decks, the most recently changed first
	// (GET /decks)
	ListDecks(ctx context.Context, request ListDecksRequestObject) (ListDecksResponseObject, error)
	// CreateDeck Create a deck
	// (POST /decks)
	CreateDeck(ctx context.Context, request CreateDeckRequestObject) (CreateDeckResponseObject, error)
	// ReadDeckList Read a deck list written as text
	// (POST /decks/text)
	ReadDeckList(ctx context.Context, request ReadDeckListRequestObject) (ReadDeckListResponseObject, error)
	// DeleteDeck Delete a deck
	// (DELETE /decks/{deckId})
	DeleteDeck(ctx context.Context, request DeleteDeckRequestObject) (DeleteDeckResponseObject, error)
	// GetDeck One of the player's decks, with its cards and legality
	// (GET /decks/{deckId})
	GetDeck(ctx context.Context, request GetDeckRequestObject) (GetDeckResponseObject, error)
	// UpdateDeck Replace a deck
	// (PUT /decks/{deckId})
	UpdateDeck(ctx context.Context, request UpdateDeckRequestObject) (UpdateDeckResponseObject, error)
	// GetDeckText A deck written as text
	// (GET /decks/{deckId}/text)
	GetDeckText(ctx context.Context, request GetDeckTextRequestObject) (GetDeckTextResponseObject, error)
	// ListFormats Every format, in the order admins set
	// (GET /formats)
	ListFormats(ctx context.Context, request ListFormatsRequestObject) (ListFormatsResponseObject, error)
	// GetLiveGame A running game, for its players and its spectators
	// (GET /games/{gameId})
	GetLiveGame(ctx context.Context, request GetLiveGameRequestObject) (GetLiveGameResponseObject, error)
	// OpenGameSocket Play or watch a game
	// (GET /games/{gameId}/socket)
	OpenGameSocket(ctx context.Context, request OpenGameSocketRequestObject) (OpenGameSocketResponseObject, error)
	// GetHealth Check that the server and its database are working
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetLobby The lobby as players see it
	// (GET /lobby)
	GetLobby(ctx context.Context, request GetLobbyRequestObject) (GetLobbyResponseObject, error)
	// OpenGame Open a game for an opponent to join
	// (POST /lobby/games)
	OpenGame(ctx context.Context, request OpenGameRequestObject) (OpenGameResponseObject, error)
	// CancelOpenGame Cancel an open game; only its host may
	// (DELETE /lobby/games/{openGameId})
	CancelOpenGame(ctx context.Context, request CancelOpenGameRequestObject) (CancelOpenGameResponseObject, error)
	// GetOpenGame An open game, listed or not, as its invite link shows it
	// (GET /lobby/games/{openGameId})
	GetOpenGame(ctx context.Context, request GetOpenGameRequestObject) (GetOpenGameResponseObject, error)
	// JoinOpenGame Join an open game, which starts it
	// (POST /lobby/games/{openGameId}/join)
	JoinOpenGame(ctx context.Context, request JoinOpenGameRequestObject) (JoinOpenGameResponseObject, error)
	// GetMatch A finished game
	// (GET /matches/{gameId})
	GetMatch(ctx context.Context, request GetMatchRequestObject) (GetMatchResponseObject, error)
	// GetPlayer A player's profile
	// (GET /players/{username})
	GetPlayer(ctx context.Context, request GetPlayerRequestObject) (GetPlayerResponseObject, error)
	// GetPlayerMatches A player's match history
	// (GET /players/{username}/matches)
	GetPlayerMatches(ctx context.Context, request GetPlayerMatchesRequestObject) (GetPlayerMatchesResponseObject, error)
	// LeaveQuickMatch Stop waiting for a quick match
	// (DELETE /quick-match)
	LeaveQuickMatch(ctx context.Context, request LeaveQuickMatchRequestObject) (LeaveQuickMatchResponseObject, error)
	// GetQuickMatch Quick match as the player sees it
	// (GET /quick-match)
	GetQuickMatch(ctx context.Context, request GetQuickMatchRequestObject) (GetQuickMatchResponseObject, error)
	// EnterQuickMatch Wait for a quick match
	// (POST /quick-match)
	EnterQuickMatch(ctx context.Context, request EnterQuickMatchRequestObject) (EnterQuickMatchResponseObject, error)
	// GetRankings The rankings
	// (GET /rankings)
	GetRankings(ctx context.Context, request GetRankingsRequestObject) (GetRankingsResponseObject, error)
	// OpenRealtime Open the live connection
	// (GET /realtime)
	OpenRealtime(ctx context.Context, request OpenRealtimeRequestObject) (OpenRealtimeResponseObject, error)
	// DeclineRematch Decline the rematch, or leave it for the lobby
	// (DELETE /rematches/{gameId})
	DeclineRematch(ctx context.Context, request DeclineRematchRequestObject) (DeclineRematchResponseObject, error)
	// GetRematch The rematch of a game that just ended, for its players
	// (GET /rematches/{gameId})
	GetRematch(ctx context.Context, request GetRematchRequestObject) (GetRematchResponseObject, error)
	// ChooseRematchDeck Switch to another deck for the rematch
	// (PUT /rematches/{gameId}/deck)
	ChooseRematchDeck(ctx context.Context, request ChooseRematchDeckRequestObject) (ChooseRematchDeckResponseObject, error)
	// AgreeToRematch Offer the rematch, or accept the other player's
	// (POST /rematches/{gameId}/ready)
	AgreeToRematch(ctx context.Context, request AgreeToRematchRequestObject) (AgreeToRematchResponseObject, error)
	// GetSiteStats How many players are online and games running
	// (GET /stats)
	GetSiteStats(ctx context.Context, request GetSiteStatsRequestObject) (GetSiteStatsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

